"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One icon button in the row. */
export interface GlidingTooltipItem {
  id: string;
  /** Names the button for screen readers and fills the tooltip. */
  label: string;
  icon: ReactNode;
  /** Shown as a key in the tooltip, for example "⌘B". */
  shortcut?: string;
  /** The same shortcut in `aria-keyshortcuts` form, for example "Meta+B". */
  keyShortcuts?: string;
  onSelect?: () => void;
  disabled?: boolean;
}

/** Props for a row of icon buttons that share one tooltip. */
export type GlidingTooltipProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  items: GlidingTooltipItem[];
  /** Runs with the id of the pressed button, after that button's own `onSelect`. */
  onAction?: (id: string) => void;
  /** Milliseconds a pointer rests on the first button before the tooltip shows. Neighbours then answer at once. */
  openDelay?: number;
};

// Critically damped: the tooltip follows the pointer and settles without a wobble.
const GLIDE: Transition = { type: "spring", stiffness: 600, damping: 49, mass: 1 };
const ENTER: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };
const EXIT: Transition = { duration: 0.12, ease: [0.165, 0.84, 0.44, 1] };
const SWAP: Transition = { duration: 0.12 };
const INSTANT: Transition = { duration: 0 };

/**
 * A row of icon buttons with one shared tooltip. Moving to a neighbour glides
 * the same tooltip across and swaps its text, so it never closes and reopens.
 */
export function GlidingTooltip({ items, onAction, openDelay = 300, className, ...rootProps }: GlidingTooltipProps) {
  // `x` is the centre of the active button, measured from the left edge of the row.
  const [tip, setTip] = useState<{ id: string; x: number } | null>(null);
  const reduceMotion = useReducedMotion();
  const delay = useRef(0);
  const shown = items.find((item) => item.id === tip?.id);

  useEffect(() => () => window.clearTimeout(delay.current), []);

  useEffect(() => {
    if (!tip) return;
    const hideOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setTip(null);
    };
    document.addEventListener("keydown", hideOnEscape);
    return () => document.removeEventListener("keydown", hideOnEscape);
  }, [tip]);

  const show = (id: string, button: HTMLElement, wait: number) => {
    window.clearTimeout(delay.current);
    const next = { id, x: button.offsetLeft + button.offsetWidth / 2 };
    if (wait > 0) delay.current = window.setTimeout(() => setTip(next), wait);
    else setTip(next);
  };

  const hide = () => {
    window.clearTimeout(delay.current);
    setTip(null);
  };

  return (
    <div
      role="group"
      {...rootProps}
      onPointerLeave={(event) => {
        rootProps.onPointerLeave?.(event);
        hide();
      }}
      className={cn("relative inline-flex items-center gap-1", className)}
    >
      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          aria-label={item.label}
          aria-keyshortcuts={item.keyShortcuts}
          disabled={item.disabled}
          onClick={() => {
            item.onSelect?.();
            onAction?.(item.id);
          }}
          onPointerEnter={(event) => {
            // A finger cannot hover; a tap would leave the tooltip stuck open.
            if (event.pointerType !== "touch") show(item.id, event.currentTarget, tip ? 0 : openDelay);
          }}
          onFocus={(event) => show(item.id, event.currentTarget, 0)}
          onBlur={hide}
          className={cn(
            // The button is 40px; the pseudo-element grows the hit area to 44px and meets its neighbour's.
            "relative flex size-10 shrink-0 cursor-pointer touch-manipulation items-center justify-center rounded-lg text-muted-foreground outline-none",
            "before:absolute before:-inset-0.5",
            "motion-safe:transition-colors motion-safe:duration-150 hover:bg-muted hover:text-foreground",
            "focus-visible:text-foreground focus-visible:ring-2 focus-visible:ring-ring",
            "disabled:cursor-not-allowed disabled:opacity-50",
          )}
        >
          {item.icon}
        </button>
      ))}
      <AnimatePresence>
        {tip && shown ? (
          // Hidden from screen readers: each button already carries the label and the shortcut.
          <motion.div
            key="tooltip"
            aria-hidden="true"
            data-tooltip=""
            initial={{ x: tip.x, opacity: 0, y: reduceMotion ? 0 : 4, scale: reduceMotion ? 1 : 0.96 }}
            animate={{ x: tip.x, opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, transition: EXIT }}
            // Reduced motion keeps the fade and lets the tooltip jump to the next button.
            transition={{ x: reduceMotion ? INSTANT : GLIDE, default: ENTER }}
            // A zero-width anchor: motion drives its x, and the bubble centres itself on it.
            className="pointer-events-none absolute bottom-full left-0 z-10 mb-2 w-0"
          >
            <div className="absolute bottom-0 left-0 flex -translate-x-1/2 items-center gap-2 rounded-md bg-foreground px-2 py-1 text-xs font-medium whitespace-nowrap text-background shadow-md">
              <motion.span key={shown.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={SWAP}>
                {shown.label}
              </motion.span>
              {shown.shortcut ? (
                <kbd className="rounded-sm bg-background/20 px-1 font-sans text-xs">{shown.shortcut}</kbd>
              ) : null}
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
